<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_homepage_section_keys() { return array( 'hero', 'featured-communities', 'discover-people', 'trending-interests', 'popular-discussions', 'how-it-works', 'benefits', 'guidelines', 'latest-articles', 'join-cta', 'faq', 'contact-footer-cta' ); }
function sd_homepage_sections() { $order = array_map( 'sanitize_key', explode( ',', (string) sd_homepage_get( 'sd_homepage_order' ) ) ); $allowed = sd_homepage_section_keys(); $order = array_values( array_intersect( $order, $allowed ) ); foreach ( $allowed as $key ) { if ( ! in_array( $key, $order, true ) ) { $order[] = $key; } } return $order; }
function sd_homepage_section_enabled( $key ) { $map = array( 'hero' => 'sd_home_hero_enabled', 'featured-communities' => 'sd_home_groups_enabled', 'discover-people' => 'sd_home_people_enabled', 'trending-interests' => 'sd_home_interests_enabled', 'popular-discussions' => 'sd_home_discussions_enabled', 'how-it-works' => 'sd_home_how_enabled', 'benefits' => 'sd_home_benefits_enabled', 'guidelines' => 'sd_home_guidelines_enabled', 'latest-articles' => 'sd_home_articles_enabled', 'join-cta' => 'sd_home_cta_enabled', 'faq' => 'sd_home_faq_enabled', 'contact-footer-cta' => 'sd_home_contact_enabled' ); return isset( $map[ $key ] ) ? (bool) sd_homepage_get( $map[ $key ] ) : false; }
function sd_homepage_render_section( $key ) { if ( ! sd_homepage_section_enabled( $key ) ) { return; } $templates = array( 'hero' => 'hero', 'featured-communities' => 'featured-communities', 'discover-people' => 'discover-people', 'trending-interests' => 'trending-interests', 'popular-discussions' => 'popular-discussions', 'how-it-works' => 'how-it-works', 'benefits' => 'benefits', 'guidelines' => 'guidelines', 'latest-articles' => 'latest-articles', 'join-cta' => 'join-cta', 'faq' => 'faq', 'contact-footer-cta' => 'contact-footer-cta' ); if ( isset( $templates[ $key ] ) ) { get_template_part( 'template-parts/homepage/' . $templates[ $key ] ); } }
